fn mall_equal1(v: &[i32]) -> bool {
    // For slices of length 0 or 1, all elements are trivially equal
    if v.len() < 2 {
        return true;
    }
    // Take the first element and compare it to all others
    let first = v[0];
    for &elem in &v[1..] {
        if elem != first {
            return false;
        }
    }
    true
}

